"""Expanded meal database for BeForma Nutrition API.

Contains 360 meals total: 120 breakfast, 120 lunch, 120 dinner.
Every meal includes macro values, ingredient grams, dietary tags, protein source, and an image URL.
"""
from __future__ import annotations
from typing import TypedDict

class FoodItem(TypedDict):
    food_name: str
    quantity_g: float

class MealRecord(TypedDict):
    name: str
    meal_type: str
    calories: float
    protein: float
    carbs: float
    fat: float
    protein_source: str
    dietary_tags: list[str]
    items: list[FoodItem]
    image: str

